package com.amora.app;
import android.content.Context;import android.os.Handler;import android.os.Looper;import android.webkit.WebView;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
public final class WebUpdates {
 static final String BASE="https://delta-1.github.io/-N-amora/docs/";static final AtomicBoolean busy=new AtomicBoolean();static final Handler main=new Handler(Looper.getMainLooper());static JSONObject available;static boolean initialized;
 static File dir(Context c,String n){return new File(new File(c.getFilesDir(),"amora-web-v1"),n);}static void remove(File f){File[] a=f.listFiles();if(a!=null)for(File x:a)remove(x);f.delete();}
 static void recover(Context c){if(initialized)return;initialized=true;if(c.getSharedPreferences("amora-updates",0).getBoolean("pending",false))rollback(c);try{JSONObject bundled=new JSONObject(new String(read(c.getAssets().open("web/web-update.json"),262144),StandardCharsets.UTF_8));if(dir(c,"active").exists()&&required(bundled.optString("version","4.0.0"),current(c).optString("version","4.0.0"))){remove(dir(c,"active"));remove(dir(c,"backup"));}}catch(Exception ignored){}}
 static void rollback(Context c){remove(dir(c,"active"));dir(c,"backup").renameTo(dir(c,"active"));c.getSharedPreferences("amora-updates",0).edit().putBoolean("pending",false).apply();}
 static InputStream open(Context c,String path)throws IOException{File f=new File(dir(c,"active"),path);return f.isFile()?new FileInputStream(f):c.getAssets().open("web/"+path);}
 static byte[] read(InputStream in,int max)throws IOException{try(InputStream source=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=source.read(b))!=-1){if((total+=n)>max)throw new IOException("Too large");out.write(b,0,n);}return out.toByteArray();}}
 static JSONObject current(Context c){try{return new JSONObject(new String(read(open(c,"web-update.json"),262144),StandardCharsets.UTF_8));}catch(Exception e){return new JSONObject();}}
 static String nativeVersion(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;}catch(Exception e){return "4.0.0";}}
 static boolean required(String needed,String actual){try{String[] a=needed.split("\\."),b=actual.split("\\.");for(int i=0;i<3;i++){int x=i<a.length?Integer.parseInt(a[i]):0,y=i<b.length?Integer.parseInt(b[i]):0;if(x!=y)return x>y;}return false;}catch(Exception e){return true;}}
 static byte[] download(String path,int max)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("Cache-Control","no-cache");try{if(c.getResponseCode()!=200||c.getContentLengthLong()>max)throw new IOException("Unavailable");return read(c.getInputStream(),max);}finally{c.disconnect();}}
 static String sha(byte[] data)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
 public static void check(Context c){if(!busy.compareAndSet(false,true))return;new Thread(()->{try{JSONObject m=new JSONObject(new String(download("web-update.json?check="+System.currentTimeMillis(),262144),StandardCharsets.UTF_8));if(required(m.optString("minNativeVersion","4.0.0"),nativeVersion(c)))return;if(required(current(c).optString("version","4.0.0"),m.optString("version","0.0.0")))return;if(!m.getString("id").equals(current(c).optString("id"))){available=m;NativeBridge.event("webUpdate",new JSONObject().put("available",true).put("version",m.optString("version")));}}catch(Exception ignored){}finally{busy.set(false);}},"Amora-update-check").start();}
 public static void install(Context c){if(available==null||!busy.compareAndSet(false,true))return;new Thread(()->{try{JSONObject m=available;JSONArray files=m.getJSONArray("files");if(files.length()>120)throw new IOException();File stage=dir(c,"stage");remove(stage);stage.mkdirs();long total=0;boolean index=false;for(int i=0;i<files.length();i++){JSONObject e=files.getJSONObject(i);String path=e.getString("path");int size=e.getInt("size");if(path.startsWith("/")||path.contains("..")||!path.matches("[A-Za-z0-9/_.,@-]+")||size<0||size>4194304||(total+=size)>12582912)throw new IOException();byte[] data=download(path,size+1);if(data.length!=size||!sha(data).equals(e.getString("sha256")))throw new IOException();File f=new File(stage,path);f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){out.write(data);}if(path.equals("index.html"))index=true;}if(!index)throw new IOException();try(FileOutputStream out=new FileOutputStream(new File(stage,"web-update.json"))){out.write(m.toString().getBytes(StandardCharsets.UTF_8));}remove(dir(c,"backup"));if(dir(c,"active").exists()&&!dir(c,"active").renameTo(dir(c,"backup")))throw new IOException();if(!stage.renameTo(dir(c,"active"))){rollback(c);throw new IOException();}c.getSharedPreferences("amora-updates",0).edit().putBoolean("pending",true).apply();available=null;main.post(()->{for(WebView w:new ArrayList<>(AmoraWeb.views)){AmoraWeb.readyViews.remove(w);w.reload();}main.postDelayed(()->{if(c.getSharedPreferences("amora-updates",0).getBoolean("pending",false)){rollback(c);for(WebView w:new ArrayList<>(AmoraWeb.views))w.reload();NativeBridge.event("info","Voltamos à versão anterior. Tente atualizar novamente depois.");}},25000);});}catch(Exception e){remove(dir(c,"stage"));NativeBridge.event("updateError","Não foi possível atualizar. A versão atual continua disponível. Tente novamente com internet estável.");}finally{busy.set(false);}},"Amora-update-install").start();}
 public static void ready(Context c){if(c.getSharedPreferences("amora-updates",0).getBoolean("pending",false)){c.getSharedPreferences("amora-updates",0).edit().putBoolean("pending",false).apply();remove(dir(c,"backup"));}}
}
